/**
 * Content access layer — the app's only door to `src/content/generated/content.json`
 * (produced by scripts/build-content.mjs from content/*.md; CONTRACT §4/§5).
 *
 * The bundle is re-validated with the zod schema at import time. The build
 * script already validates, so a failure here means the JSON was hand-edited
 * or generated by a stale/mismatched pipeline — throw loudly, do not degrade.
 */
import raw from './generated/content.json';
import { SiteContentSchema } from './schema';
import type { Project, Post, SiteContent } from './schema';

export type { Project, Post, Video, Talk, ProjectLinks, ProjectMetric } from './schema';
export type { SiteContent };
export { ProjectSchema, PostSchema, VideoSchema, TalkSchema } from './schema';

function validate(): SiteContent {
  const parsed = SiteContentSchema.safeParse(raw);
  if (!parsed.success) {
    const first = parsed.error.issues
      .slice(0, 5)
      .map((i) => `  ${i.path.join('.')}: ${i.message}`)
      .join('\n');
    throw new Error(
      `content: generated/content.json does not match SiteContentSchema — ` +
        `rebuild with \`node scripts/build-content.mjs\`.\n${first}`,
    );
  }
  const { generatedAt: _generatedAt, ...site } = parsed.data;
  return site;
}

export const content: SiteContent = validate();

export function getProject(slug: string): Project | undefined {
  return content.projects.find((p) => p.slug === slug);
}

export function getPost(slug: string): Post | undefined {
  return content.posts.find((p) => p.slug === slug);
}

/** Newest first; date-identical entries keep stable slug order. */
export function postsByDate(): Post[] {
  return [...content.posts].sort(
    (a, b) => (a.date === b.date ? a.slug.localeCompare(b.slug) : a.date < b.date ? 1 : -1),
  );
}

export function featuredProjects(): Project[] {
  return content.projects.filter((p) => p.featured);
}

/** Tag frequency across every content type, count desc then alphabetical. */
export function allTags(): { tag: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const item of [...content.projects, ...content.posts, ...content.videos, ...content.talks]) {
    for (const tag of item.tags) counts.set(tag, (counts.get(tag) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([tag, count]) => ({ tag, count }))
    .sort((a, b) => b.count - a.count || a.tag.localeCompare(b.tag));
}
